// Build the Gemini request for one discrepancy case
return $input.all().map(i => {
  const c = i.json;

  // Stop early if the case data did not arrive (prevents the AI inventing a case)
  if (!c.po_number || !c.line_id) {
    throw new Error('Workflow 3 received a case without po_number/line_id. Input was: ' + JSON.stringify(c).slice(0, 200));
  }

  const system =
    'You are a warehouse receiving analyst. Given a reconciliation discrepancy between a purchase order, ' +
    'delivery note, warehouse scan and supplier invoice, respond with ONLY a JSON object with keys: ' +
    '"summary" (max 80 words, formal tone, suitable for a supplier claim letter, state the PO number, the quantities and the amount), ' +
    '"recommended_action" (one of: file_supplier_claim, request_credit_note, request_replacement, fix_sku_mapping, accept_variance), ' +
    '"severity" (one of: low, medium, high). ' +
    'Use only the figures provided; do not invent PO numbers, invoice numbers, SKUs or amounts. ' +
    'If the category is unmapped_sku or sku_mismatch, recommend fix_sku_mapping and explain that the supplier code could not be matched.';

  const user = JSON.stringify({
    po_number: c.po_number,
    internal_sku: c.internal_sku,
    categories: c.categories,
    ordered_qty: c.ordered_qty,
    delivered_qty: c.delivered_qty,
    scanned_good_qty: c.scanned_good_qty,
    scanned_damaged_qty: c.scanned_damaged_qty,
    invoiced_qty: c.invoiced_qty,
    unit_price: c.unit_price,
    claim_amount: c.claim_amount,
    unmapped_codes: c.unmapped_codes,
    mismatched_codes: c.mismatched_codes,
  });

  return { json: {
    case: c,
    request_body: {
      systemInstruction: { parts: [{ text: system }] },
      contents: [{ role: 'user', parts: [{ text: user }] }],
      generationConfig: { temperature: 0.2, responseMimeType: 'application/json' },
    },
  } };
});

// Parse AI response — accepts AI Agent output ({ output }) or raw Gemini REST output ({ candidates })
const c = $('Build prompt').first().json.case;
const resp = $input.first().json;

let ai;
if (resp.output && typeof resp.output === 'object') {
  ai = resp.output;                                   // Agent with a structured output parser
} else {
  const raw = typeof resp.output === 'string'
    ? resp.output                                     // AI Agent node
    : (resp.candidates?.[0]?.content?.parts ?? []).map(p => p.text ?? '').join('');  // HTTP Request to Gemini
  if (!raw.trim()) {
    throw new Error('AI returned no answer: ' + JSON.stringify(resp).slice(0, 300));
  }
  // Remove reasoning blocks some open models emit (e.g. <think>...</think>) before looking for the JSON
  const text = raw.replace(/<think>[\s\S]*?<\/think>/gi, '');
  const start = text.indexOf('{'), end = text.lastIndexOf('}');
  if (start === -1 || end <= start) {
    throw new Error('AI answer contains no complete JSON object (it may be prose, or cut off by the token limit). End of answer: ' + raw.slice(-150));
  }
  try { ai = JSON.parse(text.slice(start, end + 1)); }
  catch (e) { throw new Error('AI returned invalid JSON: ' + raw.slice(0, 200)); }
}

const summary = String(ai.summary ?? '').trim();
if (!summary) throw new Error('AI response has no summary');
// Guard against invented figures: the summary must name the PO it is about
if (!summary.toUpperCase().includes(String(c.po_number).toUpperCase())) {
  throw new Error(`AI summary does not mention ${c.po_number}; the case data probably did not reach the model. Summary: ${summary.slice(0, 150)}`);
}

const ACTIONS = ['file_supplier_claim', 'request_credit_note', 'request_replacement', 'fix_sku_mapping', 'accept_variance'];
const act = String(ai.recommended_action ?? '').trim().toLowerCase();
const recommended_action = ACTIONS.includes(act) ? act : 'file_supplier_claim';
const sev = String(ai.severity ?? '').trim().toLowerCase();
const severity = ['low', 'medium', 'high'].includes(sev) ? sev : 'medium';
const now = new Date().toISOString();

return [{ json: {
  case_id: `CASE-${c.line_id}-${Date.now()}`,
  po_number: c.po_number,
  internal_sku: c.internal_sku,
  categories: (c.categories || []).join(', '),
  ordered_qty: c.ordered_qty,
  delivered_qty: c.delivered_qty,
  scanned_good_qty: c.scanned_good_qty,
  scanned_damaged_qty: c.scanned_damaged_qty,
  invoiced_qty: c.invoiced_qty,
  claim_amount: c.claim_amount,
  ai_summary: summary,
  recommended_action,
  severity,
  approval_status: 'pending',
  created_at: now,
  resolved_at: '',
  line_id: c.line_id,
} }];

