// Build decision writes — turn the reviewer's decision into sheet write-backs.
// Updates the case, the PO line AND the delivery, scan and invoice rows behind it,
// so all four documents end in the same state (approved / rejected).
const approved = $input.first().json.data?.approved === true;
const c = $('Parse AI response').first().json;          // the case as written to Investigations
const src = $('Build prompt').first().json.case || {};   // the original line from workflow 2 (holds the document IDs)
const ts = new Date().toISOString();
const decision = approved ? 'approved' : 'rejected';

const out = [
  { json: { target: 'INVESTIGATION', case_id: c.case_id, approval_status: decision, resolved_at: ts } },
  { json: { target: 'PO', line_id: c.line_id, status: decision } },
];
(src.delivery_ids || []).forEach(id => out.push({ json: { target: 'DELIVERY', delivery_id: id, status: decision } }));
(src.scan_ids || []).forEach(id => out.push({ json: { target: 'SCAN', scan_id: id, status: decision } }));
(src.invoice_ids || []).forEach(id => out.push({ json: { target: 'INVOICE', invoice_id: id, status: decision } }));

out.push({ json: {
  target: 'AUDIT',
  log_id: `LOG-${Date.now()}-D`,
  timestamp: ts,
  po_number: c.po_number,
  internal_sku: c.internal_sku,
  event: approved ? 'CLAIM_APPROVED' : 'CLAIM_REJECTED',
  actor: 'human:reviewer',
  old_value: 'discrepancy',
  new_value: decision,
  details: JSON.stringify({
    case_id: c.case_id, claim_amount: c.claim_amount, severity: c.severity,
    recommended_action: c.recommended_action, summary: c.ai_summary,
    delivery_ids: src.delivery_ids || [], scan_ids: src.scan_ids || [], invoice_ids: src.invoice_ids || [],
  }),
} });
return out;

